const raw=$('Webhook').first().json.body||{};
const b=(raw.payload&&typeof raw.payload==='object')?{...raw.payload,device_id:raw.device_id||raw.payload.device_id,session_id:raw.session_id||raw.payload.session_id,event:raw.event||raw.payload.event}:raw;
let phone=String(b.pengirim||b.sender||b.from||'').replace(/\D/g,'');
if(phone.startsWith('0')) phone='62'+phone.slice(1);
if(phone.startsWith('8')) phone='62'+phone;
const msg=String(b.body||b.message||b.pesan||b.text||'');
const image=String(typeof b.image==='string'?b.image:(b.image&&b.image.path)||b.document||b.video||b.audio||'');
const isAdmin=phone==='6282192791079';
return [{json:{...b,sender_phone:phone,message_text:msg,message_type:String(b.type|| (image?'image':'text')).toLowerCase(),sender_role:isAdmin?'barber':'unknown',is_admin:isAdmin,display_name:String(b.sender_display_name||b.from_name||b.name||''),gowa_message_id:String(b.id||''),gowa_device_id:String(b.device_id||b.session_id||'barber-wa'),gowa_image:image}}];

const x=$input.first().json;
const b=$('Normalize Incoming Sender').first().json;
const type=String(b.type||b.message_type||'').toLowerCase();
const message=String(b.message||b.message_text||b.caption||'').trim().toLowerCase();
const url=String(b.url||b.file_url||b.media_url||b.gowa_image||'');
const filename=String(b.filename||b.file_name||url.split('/').pop()||'');
const choices=Array.isArray(b.choices)?b.choices:[];
const isMediaType=['image','photo','document','file','audio','video','sticker'].some(k=>type.includes(k));
const isGowaMedia=Boolean(b.image||b.document||b.video||b.audio||b.gowa_image);
const isFonnteNonText=message==='non-text message'||String(b.text||'').toLowerCase()==='non-button message'&&message==='non-text message';
const hasMedia=isMediaType||isGowaMedia||isFonnteNonText||Boolean(url)||Boolean(filename);
// Pesan konsultasi rambut harus mengalahkan detektor bukti pembayaran.
const hairIntent=/(saran|rekomendasi|model rambut|gaya rambut|potongan rambut|warna rambut|cocok|preview|edit rambut|rambut)/i.test(message);
const paymentIntent=/(bukti transfer|bukti pembayaran|sudah transfer|sudah bayar|pembayaran|transfer|qris|rekening|struk pembayaran|payment)/i.test(message);
const isPaymentProof=hasMedia && !hairIntent && (paymentIntent || message==='' || message==='non-text message');
return [{json:{...x,...b,is_payment_proof:isPaymentProof,has_media:hasMedia,hair_intent:hairIntent,payment_intent:paymentIntent,proof_url:url,proof_filename:filename,proof_type:type,proof_choices:choices}}];

